        "Có thể thêm lượng từ 次 sau 过 + tân ngữ để đếm số lần đã làm, ví dụ 去过中国好几次.",
        "虽然 + mệnh đề 1，但是 + mệnh đề 2 nêu một sự việc/hoàn cảnh rồi nêu ý tương phản, đối lập với sự việc đó; hai vế có thể đổi vị trí chủ ngữ tùy ngữ cảnh.",
        "了 nhấn mạnh một sự việc cụ thể đã xảy ra hoặc hoàn thành, dùng được với động từ chỉ hành động kéo dài (跑, 看), hành động một lần (死), hoặc động từ nhận thức (知道).",
        "过 nhấn mạnh kinh nghiệm, giúp giải thích hoặc làm rõ nội dung đang nói, thường chỉ dùng với động từ chỉ hành động kéo dài, không dùng với động từ chỉ hành động một lần hay động từ nhận thức."
