        "请（+ đối tượng）+ động từ dùng để mời hoặc đề nghị một cách lịch sự; 请+V đơn (không có đối tượng cụ thể) là lời mời/gợi ý chung (请坐, 请喝茶); 请+Sb+V mời đích danh một người làm gì.",
        "V+好 làm bổ ngữ kết quả, diễn tả hành động đã hoàn thành và đạt yêu cầu, kết quả tốt đẹp; khác với V+完 chỉ đơn thuần diễn tả hành động đã hoàn thành. Các bổ ngữ kết quả khác cùng nhóm: 开, 见, 到 (đi với động từ) và 懂, 早, 晚, 错 (đi với tính từ).",
        "一 + lượng từ（+ danh từ）hoặc 一点儿（+ danh từ）+ 也 / 都 + 不 / 没 + động từ / tính từ nhấn mạnh phủ định tuyệt đối, nghĩa là 'một... cũng không / chưa...'.",
