      "patterns": [
        ["1.1 động từ + 来（hướng về phía người nói）/ 去（hướng ra xa người nói）", "来 biểu thị hướng của hành động đi về phía người nói; 去 biểu thị hướng của hành động đi ra xa người nói."],
        ["1.2 Khi tân ngữ là địa điểm: S + động từ + địa điểm + 来 / 去", "Khi tân ngữ là một địa điểm, 来/去 luôn đứng sau địa điểm đó, không đổi vị trí."],
        ["1.3 Khi tân ngữ là vật: S + động từ + vật + 来 / 去 = S + động từ + 来 / 去 + vật", "Khi tân ngữ là một vật, có hai cách nói tương đương: đặt 来/去 sau vật, hoặc đặt ngay sau động từ rồi mới đến vật."],
        ["2. S（1）+ động từ 1 + 了（+ tân ngữ 1），（S2）+ 就 + động từ 2（+ tân ngữ 2）", "Diễn tả hai hành động xảy ra liên tiếp, hành động 2 xảy ra ngay sau hành động 1; có thể dùng một chủ ngữ chung hoặc hai chủ ngữ khác nhau."],
        ["3. Mệnh đề (vẻ bề ngoài)，（但）其实 + mệnh đề (sự thật)", "Nêu vẻ bề ngoài hoặc điều người khác nghĩ, sau đó dùng 其实 để nêu sự thật, thường mang ý đính chính hoặc bổ sung thông tin."],
        ["4.1 danh từ + 怎么样？（hỏi trạng thái / ý kiến）", "Hỏi về trạng thái, chất lượng hoặc ý kiến về một sự vật, sự việc."],
        ["4.2 ... + 怎么 + động từ？（hỏi cách thức hoặc nguyên nhân）", "Hỏi về cách thức thực hiện hành động, hoặc hỏi nguyên nhân của hành động/trạng thái, thường mang sắc thái ngạc nhiên, sốt ruột."],
        ["4.3 tình huống，怎么办？（hỏi biện pháp xử lý）", "Hỏi hoặc than vãn về cách giải quyết một tình huống khó khăn."],
        ["5.1 叫（gọi tên / tên là）: S + 叫 + tên", "叫 dùng để nói hoặc hỏi tên của ai đó."],
        ["5.2 叫（đặt / gọi）: 叫 + tân ngữ（车 / 外卖 / 菜…）", "叫 dùng để nói gọi hoặc đặt một dịch vụ hay món đồ như xe, đồ ăn mang đi, món ăn."],
        ["6. 能 + mệnh đề + 吗？（câu hỏi tu từ: khẳng định mang nghĩa phủ định, phủ định mang nghĩa khẳng định）", "Dùng trong câu hỏi tu từ (phản vấn) để nhấn mạnh một kết luận hiển nhiên."]
      ],
