        "疑问代词的活用: dùng một đại từ nghi vấn hai lần trong cùng một câu để chỉ người/vật/cách thức không xác định. Các đại từ dùng được: 谁、哪儿、哪、什么、怎么. Cùng chủ ngữ thì vế sau lược được chủ ngữ; khác chủ ngữ thì phải nêu đủ cả hai, vế sau luôn có 就.",
        "一会儿 chỉ khoảng thời gian rất ngắn: đứng SAU động từ/tính từ nghĩa là \"một lát\" (你等我一会儿); đứng TRƯỚC động từ nghĩa là \"lát nữa\" (我一会儿再去).",
        "Phân biệt ba mục dễ lẫn (bảng PDF trang 8): 有（一）点儿 đứng trước tính từ/động từ tâm lý và mang ý chê (今天天气有点儿冷); 一点儿 chỉ số lượng ít, đứng sau động từ rồi tới danh từ hoặc đứng sau tính từ (我买了一点儿苹果、小一点儿的); 一会儿 chỉ thời gian ngắn. Mẹo nhớ: chê thì 有点儿, ít thì 一点儿, ngắn thì 一会儿."
