    "text": "我叫大卫，在北京大学学习汉语。每天早上六点半我都起床，七点吃早饭，八点前到学校。我最喜欢汉语，也喜欢运动。星期六我常和朋友一起踢足球。上个星期我生病了，身体不太好，没有去学校。医生说我要多休息、多喝水。现在我好多了，下个星期要和朋友去北京旅游。我的朋友李月也要去商店，她想买一块红色的手表送给丈夫。左边的那块真漂亮，一千多块钱。她先看一下，也听一下商店里的人怎么说。",
